HEALTH_FOOTER = '''### Как проверить свежесть

- **Расписание и кэш.** Витрины пересчитываются каждые 5 минут; эта таблица может хранить ответ до 15 секунд. Фильтр периода здесь не применяется.
- **После перезапуска.** Подтверждение последнего успеха может отсутствовать до нового пересчёта, даже если прежняя копия данных сохранилась.
- **Состояние сервисов.** Если таблица не загружается, проверьте доступность хранилища по сообщению ошибки. При остановленном Superset страница также будет недоступна.
- **Согласованность.** Семь витрин обновляются независимо. Их успешный пересчёт не гарантирует, что все сервисы уже доставили самые новые события.'''


def boards():
    result = []
    for original in BOARDS:
        rows = []
        for row in original.rows:
            charts = []
            for chart in row:
                title, caption, definition = CAPTIONS[chart.key]
                units = {'runs':'Забеги, шт.', 'xp':'Опыт, XP', 'level_ups':'Повышения / уровни',
                    'level_gifts':'Подарки, шт.', 'case_openings':'Открытия, шт.',
                    'shop_purchases':'Выдачи, шт.', 'event_delivery':'События, шт.'}.get(chart.dataset,'')
                if chart.key == 'balance-daily': units = 'Убийств / забег'
                if chart.key == 'shop-spend': units = 'Престиж, ед.'
                is_line = chart.kind == 'echarts_timeseries_line'
                is_bar = chart.kind == 'echarts_timeseries_bar'
                charts.append(replace(chart, title=title, subheader=caption, description=definition,
                    guide=definition if chart.kind != 'big_number_total' else '',
                    x_title='День · UTC' if is_line else ('Уровень награды' if chart.key=='gifts-level' else 'Уровень церкви') if is_bar else '',
                    y_title=units if is_line or is_bar else '',
                    height={'bi-freshness':62,'shop-catalog':55,'events-contracts':55,'cases-catalog':47}.get(chart.key,chart.height)))
            rows.append(tuple(charts))
        title, question = PURPOSE[original.slug]
        result.append(replace(original, rows=tuple(rows), note='### '+title+'\n\n'+question,
            intro_sections=SECTIONS[original.slug], show_limit_note=False,
            footer=COMMON_FOOTER if original.show_period else HEALTH_FOOTER, footer_height=34))
    return result
